window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e0196f0a5d492f63"]={"versions": [{"id": "FIG-e0196f0a5d492f63", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm definiert die strukturelle Einbettung des internen Verhaltens (<code>AdaptiveSwcInternalBehavior</code>) in Software-Komponententypen sowie dessen Aggregation von Service-Abhängigkeiten (<code>SwcServiceDependency</code>) im Kontext des Diagnose-Mappings (<code>DiagnosticMapping</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>AdaptiveApplicationSwComponentType</strong> (spezialisiert <code>SwComponentType</code>): Repräsentiert den Komponententyp einer Adaptive-Anwendung.\n</li><li><strong>AdaptiveSwcInternalBehavior</strong> (spezialisiert <code>Identifiable</code>): Beschreibt das interne Verhalten der Adaptive-Software-Komponente. Wird von <code>AdaptiveApplicationSwComponentType</code> über die Kompositionsrolle <code>+internalBehavior</code> mit der Multiplizität <code>0..1</code> aggregiert. Die Aggregation ist mit den Stereotypen <code>«atpVariation,atpSplitable»</code> versehen.\n</li><li><strong>SwcServiceDependency</strong> (spezialisiert <code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>): Definiert die funktionale Abhängigkeit der Komponente von AUTOSAR-Diensten. Wird von <code>AdaptiveSwcInternalBehavior</code> über die Kompositionsrolle <code>+serviceDependency</code> mit der Multiplizität <code>0..*</code> aggregiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es sind keine dynamischen Interaktionen, Laufzeitsequenzen oder Zustandsübergänge dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Eine <code>AdaptiveApplicationSwComponentType</code> darf maximal ein internes Verhalten besitzen (<code>0..1</code>).\n</li><li>Die Assoziation <code>+internalBehavior</code> unterliegt dem AUTOSAR-Variantenhandling (<code>«atpVariation»</code>) und kann über verschiedene Modellbeschreibungsdateien aufgeteilt werden (<code>«atpSplitable»</code>).\n</li><li>Ein <code>AdaptiveSwcInternalBehavior</code> kann beliebig viele Service-Abhängigkeiten (<code>0..*</code>) über <code>+serviceDependency</code> definieren, die als Ziel für <code>DiagnosticMapping</code> herangezogen werden können.\n</li></ul>"}, {"id": "FIG-b0e9059b3b7456b4", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm definiert die strukturelle Einbettung des internen Verhaltens (<code>AdaptiveSwcInternalBehavior</code>) in Software-Komponententypen sowie dessen Aggregation von Service-Abhängigkeiten (<code>SwcServiceDependency</code>) im Kontext des Diagnose-Mappings (<code>DiagnosticMapping</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>AdaptiveApplicationSwComponentType</strong> (spezialisiert <code>SwComponentType</code>): Repräsentiert den Komponententyp einer Adaptive-Anwendung.\n</li><li><strong>AdaptiveSwcInternalBehavior</strong> (spezialisiert <code>Identifiable</code>): Beschreibt das interne Verhalten der Adaptive-Software-Komponente. Wird von <code>AdaptiveApplicationSwComponentType</code> über die Kompositionsrolle <code>+internalBehavior</code> mit der Multiplizität <code>0..1</code> aggregiert. Die Aggregation ist mit den Stereotypen <code>«atpVariation,atpSplitable»</code> versehen.\n</li><li><strong>SwcServiceDependency</strong> (spezialisiert <code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>): Definiert die funktionale Abhängigkeit der Komponente von AUTOSAR-Diensten. Wird von <code>AdaptiveSwcInternalBehavior</code> über die Kompositionsrolle <code>+serviceDependency</code> mit der Multiplizität <code>0..*</code> aggregiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es sind keine dynamischen Interaktionen, Laufzeitsequenzen oder Zustandsübergänge dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Eine <code>AdaptiveApplicationSwComponentType</code> darf maximal ein internes Verhalten besitzen (<code>0..1</code>).\n</li><li>Die Assoziation <code>+internalBehavior</code> unterliegt dem AUTOSAR-Variantenhandling (<code>«atpVariation»</code>) und kann über verschiedene Modellbeschreibungsdateien aufgeteilt werden (<code>«atpSplitable»</code>). Für <code>«atpVariation»</code> gelten die Tagged Values <code>atp.Status = draft</code> sowie <code>vh.latestBindingTime = preCompileTime</code>.\n</li><li>Ein <code>AdaptiveSwcInternalBehavior</code> kann beliebig viele Service-Abhängigkeiten (<code>0..*</code>) über <code>+serviceDependency</code> definieren, die als Ziel für <code>DiagnosticMapping</code> herangezogen werden können.\n</li></ul>"}, {"id": "FIG-52927dc550fb6aeb", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm definiert die strukturelle Einbettung des internen Verhaltens (<code>AdaptiveSwcInternalBehavior</code>) in Software-Komponententypen sowie dessen Aggregation von Service-Abhängigkeiten (<code>SwcServiceDependency</code>) im Kontext des Diagnose-Mappings (<code>DiagnosticMapping</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>AdaptiveApplicationSwComponentType</strong> (spezialisiert <code>SwComponentType</code>): Repräsentiert den Komponententyp einer Adaptive-Anwendung.\n</li><li><strong>AdaptiveSwcInternalBehavior</strong> (spezialisiert <code>Identifiable</code>): Beschreibt das interne Verhalten der Adaptive-Software-Komponente. Wird von <code>AdaptiveApplicationSwComponentType</code> über die Kompositionsrolle <code>+internalBehavior</code> mit der Multiplizität <code>0..1</code> aggregiert. Die Aggregation ist mit den Stereotypen <code>«atpVariation,atpSplitable»</code> versehen.\n</li><li><strong>SwcServiceDependency</strong> (spezialisiert <code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>): Definiert die funktionale Abhängigkeit der Komponente von AUTOSAR-Diensten. Wird von <code>AdaptiveSwcInternalBehavior</code> über die Kompositionsrolle <code>+serviceDependency</code> mit der Multiplizität <code>0..*</code> aggregiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es sind keine dynamischen Interaktionen, Laufzeitsequenzen oder Zustandsübergänge dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Eine <code>AdaptiveApplicationSwComponentType</code> darf maximal ein internes Verhalten besitzen (<code>0..1</code>).\n</li><li>Die Assoziation <code>+internalBehavior</code> unterliegt dem AUTOSAR-Variantenhandling (<code>«atpVariation»</code>) und kann über verschiedene Modellbeschreibungsdateien aufgeteilt werden (<code>«atpSplitable»</code>). Für <code>«atpVariation»</code> gelten die Tagged Values <code>atp.Status = draft</code> sowie <code>vh.latestBindingTime = preCompileTime</code>.\n</li><li>Ein <code>AdaptiveSwcInternalBehavior</code> kann beliebig viele Service-Abhängigkeiten (<code>0..*</code>) über <code>+serviceDependency</code> definieren, die als Ziel für <code>DiagnosticMapping</code> herangezogen werden können.\n</li></ul>"}], "trans": [{"from": "FIG-e0196f0a5d492f63", "to": "FIG-b0e9059b3b7456b4", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Beziehung <code>AdaptiveApplicationSwComponentType</code> zu <code>AdaptiveSwcInternalBehavior</code> (<code>+internalBehavior</code>): Ergänzung einer Notiz für <code>«atpVariation»</code> mit den Tags <code>atp.Status = draft</code> und <code>vh.latestBindingTime = preCompileTime</code>.\n</li></ul>"}, {"from": "FIG-b0e9059b3b7456b4", "to": "FIG-52927dc550fb6aeb", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
